WITH base AS (
  SELECT "NCT", "PubMed ID" AS "PMID", "Author" AS "Author", "Year", "Cancer type", "Name of ICI"
  FROM compat.clinical_trials
  WHERE LOWER("Cancer type") LIKE '%small cell%'
)
SELECT * FROM base;

WITH base AS (
  SELECT "NCT", "PubMed ID" AS "PMID", "Author" AS "Author", "Year", "Cancer type", "Original publication or Follow-up" AS original_publication_status
  FROM compat.clinical_trials
  WHERE LOWER("Cancer type") LIKE '%esophageal%' OR LOWER("Cancer type") LIKE '%gej%'
)
SELECT * FROM base;

WITH base AS (
  SELECT "NCT", "PubMed ID" AS "PMID", "Author" AS "Author", "Year", "Cancer type", "Type of follow-up given"
  FROM compat.clinical_trials
  WHERE LOWER("Cancer type") LIKE '%breast%'
)
SELECT * FROM base;

WITH base AS (
  SELECT "NCT", "PubMed ID" AS "PMID", "Author" AS "Author", "Year"
  FROM compat.clinical_trials
  WHERE LOWER("Name of ICI") LIKE '%atezolizumab%'
)
SELECT * FROM base;

WITH base AS (
  SELECT "NCT", "PubMed ID" AS "PMID", "Author" AS "Author", "Year", "Cancer type", "Follow-up duration for primary endpoint(s) in months | Overall" AS overall_followup_months
  FROM compat.clinical_trials
  WHERE LOWER("Cancer type") LIKE '%melanoma%'
)
SELECT * FROM base;

WITH base AS (
  SELECT "NCT", "PubMed ID" AS "PMID", "Cancer type", "Type of follow-up given"
  FROM compat.clinical_trials
  WHERE LOWER("Cancer type") LIKE '%pancreatic%'
)
SELECT * FROM base;

WITH base AS (
  SELECT "NCT", "PubMed ID" AS "PMID", "Author" AS "Author", "Year", "Cancer type", "Secondary endpoint"
  FROM compat.clinical_trials
  WHERE LOWER("Cancer type") LIKE '%head and neck%'
)
SELECT * FROM base;

WITH base AS (
  SELECT "NCT", "PubMed ID" AS "PMID", "Author" AS "Author", "Year", "Cancer type", "Number of arms"
  FROM compat.clinical_trials
  WHERE LOWER("Cancer type") LIKE '%mesothelioma%'
)
SELECT * FROM base;

WITH base AS (
  SELECT "NCT", "PubMed ID" AS "PMID", "Trial name", "Cancer type", "Primary endpoint", "Secondary endpoint"
  FROM compat.clinical_trials
  WHERE LOWER("Cancer type") LIKE '%melanoma%'
)
SELECT * FROM base;

WITH base AS (
  SELECT "NCT", "PubMed ID" AS "PMID", "Author" AS "Author", "Year", "Cancer type", "Trial phase", "Control arm"
  FROM compat.clinical_trials
  WHERE LOWER("Cancer type") LIKE '%small cell%' AND "Trial phase" = 'Phase 3'
)
SELECT * FROM base;

WITH base AS (
  SELECT "NCT", "PubMed ID" AS "PMID", "Trial phase", "Cancer type", "Control arm"
  FROM compat.clinical_trials
  WHERE LOWER("Cancer type") LIKE '%renal cell%' AND "Trial phase" = 'Phase 3'
)
SELECT * FROM base;
